"""Authored alternatives, 1991–2005. No new canon claims; see the development ledger.

Each row is a focus, not an automatically duplicated reward chain. Coordinates,
prerequisites, costs, guards and consequences are explicit and reviewable.
"""
from dataclasses import dataclass

@dataclass
class Focus:
    tag:str; suffix:str; title:str; desc:str; x:int; y:int
    prerequisite:tuple=(); reward:str=''; available:str=''; cost:int=5
    phase:str='opening'; excludes:tuple=()
    @property
    def id(self):return self.tag+('_ucw_exp_' if self.phase=='later' else '_exp_')+self.suffix

FOCUSES=[]
def f(tag,suffix,title,desc,x,y,prerequisite=(),reward='',available='',cost=5,phase='opening',excludes=()):
    row=Focus(tag,suffix,title,desc,x,y,tuple(prerequisite),reward,available,cost,phase,tuple(excludes));FOCUSES.append(row);return row

def prep(tag,kind):return 'set_country_flag = '+tag+'_exp_prepared_'+kind
def assessment(tag):return 'set_country_flag = '+tag+'_exp_assessment_ready'
def choice(tag,number):return 'set_country_flag = '+tag+'_exp_choice_'+str(number)+'_ready'
def recovery(n=4):return 'if = { limit = { ac_ucw_active = yes } add_to_variable = { ac_ucw_recovery = '+str(n)+' } ac_ucw_bound = yes }'
def pressure(n=-4):return 'if = { limit = { ac_ucw_active = yes } add_to_variable = { ac_ucw_pressure = '+str(n)+' } ac_ucw_bound = yes }'
def peace():return 'has_war = no'
def outcome(name):return 'has_global_flag = ac_ucw_'+('war_averted' if name=='peace' else 'outcome_'+name)
def partner(tag):return 'is_subject = no country_exists = '+tag+' NOT = { has_war_with = '+tag+' } '+tag+' = { has_capitulated = no is_subject = no }'

# Four opening programmes per country: administration/treaties, production,
# civil protection and defence. One root + 16 programme focuses + assessment.
for tag,title,desc in [
 ('ERU','The Farbanti Cabinet','The new decade opens with ministries competing over the same railway wagons, tax receipts and trained personnel. A cabinet inventory will show which promises Erusea can actually keep. Its conclusions will guide the coming years without committing the country to a continental war.'),
 ('FCU','The Treaty Secretariat','Central Usea enters 1991 with agreements that are easier to sign than to administer. The secretariat needs an account of each member\'s transport capacity, civil services and military commitments before another emergency tests the treaty.')]:
    f(tag,'opening',title,desc,10,0,reward='set_country_flag = '+tag+'_exp_opening_ready')

ERU=[
 ('registry','A Common Civil Register','District offices will reconcile household and land records. Reliable records make compensation possible when families move, although the survey requires staff who could otherwise process current business.','add_political_power = -15\nadd_stability = 0.02'),
 ('district_accounts','Audit the District Accounts','Inspectors will follow appropriations from the treasury to local suppliers. Publishing the discrepancies forces the cabinet to choose between protecting administrative discretion and opening decisions to review.',choice('ERU',2)),
 ('municipal_services','Municipal Service Boards','Water, sanitation and housing offices need a common emergency rota. Service boards will keep a list of qualified crews instead of assuming that another ministry will provide them.',prep('ERU','civil')),
 ('civil_compact','The Administrative Compact','The ministry and the districts must agree on who can requisition transport and who hears an appeal. A standing compact makes the chosen administrative policy durable, at the cost of a larger permanent payroll.','add_political_power = -25\nadd_stability = 0.02'),
 ('rail_survey','Survey the Freight Railways','A freight survey will identify junctions whose failure could isolate the industrial interior. Workshops will plan substitute routes before expansion contracts consume the available rolling stock.','add_tech_bonus = { name = ERU_exp_rail_survey bonus = 0.5 uses = 1 category = industry }'),
 ('machine_tools','Machine-Tool Contracts','Domestic firms need predictable orders to replace worn machine tools. Competitive contracts improve production knowledge without promising factories that the treasury cannot yet support.','add_tech_bonus = { name = ERU_exp_machine_tools bonus = 0.5 uses = 1 category = industry }'),
 ('freight_reserves','A Freight Reserve','Keep a reserve of serviceable locomotives and repair parts. Commercial operators will dislike idle equipment, but the reserve will make later relief and reconstruction less dependent on military transport.',prep('ERU','logistics')+'\nadd_political_power = -25'),
 ('industrial_standards','Common Workshop Standards','Interchangeable fittings and common inspection sheets sound unambitious beside a new industrial complex. They keep existing machinery running and give smaller firms a route into government contracts.','add_tech_bonus = { name = ERU_exp_industrial_standards bonus = 0.75 uses = 1 category = industry }'),
 ('defence_inventory','Inventory the Defence Establishment','The services will report equipment availability rather than paper strength. Repair queues and shortages of instructors will decide the first round of allocations.','army_experience = 8\nair_experience = 5'),
 ('air_maintenance','Airfield Maintenance Teams','Runway crews and dispersed spares are less visible than a new squadron. Training them now keeps the air arm useful when a damaged main base cannot service every aircraft.','air_experience = 12'),
 ('coastal_watch','A Coastal Watch Network','Civil harbour offices and naval stations will exchange shipping reports. A shared reporting schedule improves warning without treating every foreign merchant as a hostile contact.','navy_experience = 12'),
 ('reserve_exercises','Exercise the Reserve System','A limited mobilisation exercise will test rail timetables, medical screening and equipment issue. The government will retain its results for a future crisis instead of keeping the reservists under arms.',prep('ERU','readiness')+'\narmy_experience = 10'),
 ('consular_contacts','Reopen Continental Contacts','Consular officials can discuss lost cargoes, missing documents and cross-border travel even when the cabinets disagree. Such routine contacts keep a channel open for harder negotiations.','add_political_power = -15\nadd_stability = 0.01'),
 ('customs_review','Review Customs Practice','Clear rules at the frontier reduce arbitrary delays. The cabinet must decide whether the border administration should prioritise predictable civilian access or the discretion of security officers.',choice('ERU',3)),
 ('emergency_protocols','Civil Emergency Protocols','Districts will rehearse evacuation and temporary shelter for ordinary industrial accidents and severe weather. This is preparedness for known civil hazards, not foreknowledge of Ulysses.',prep('ERU','relief')+'\nadd_political_power = -20'),
 ('continental_desk','A Permanent Continental Desk','A permanent desk will keep the records from customs, consular and relief offices together. In a later crisis the cabinet will inherit an institution rather than a pile of unconnected memoranda.','add_stability = 0.02')]
FCU=[
 ('treaty_register','Register the Treaty Commitments','Every partner has signed commitments expressed in different units and deadlines. A common register will reveal where several promises depend on the same limited transport or staff.','add_political_power = 15'),
 ('burden_formula','A Formula for Shared Burdens','Population, revenue and exposed infrastructure give different answers to the question of a fair contribution. The secretariat must choose a rule before an emergency makes every transfer politically explosive.',choice('FCU',2)),
 ('liaison_offices','Permanent Liaison Offices','Seconded civilian officers will maintain contacts between ministries. Their work makes relief allocations more dependable, while reducing the number of staff available for domestic programmes.',prep('FCU','civil')),
 ('treaty_audit','Audit Collective Promises','The treaty council will publish which contributions have arrived and which remain promises. An honest shortfall is easier to plan around than a nominal surplus.','add_stability = 0.02\nadd_political_power = -20'),
 ('transport_map','Map the Continental Corridors','Survey roads, railheads and harbours as a connected transport system. The resulting priorities will serve commercial trade as well as emergency mobilisation.','add_tech_bonus = { name = FCU_exp_transport_map bonus = 0.5 uses = 1 category = industry }'),
 ('port_schedules','Coordinate Harbour Schedules','Harbours must agree on cargo documents and berth allocation. Shared schedules reduce delays without giving the secretariat ownership of national ports.','navy_experience = 8'),
 ('relief_stockpiles','Regional Relief Stores','Rotate food, medical supplies and engineering spares through regional stores. Maintaining the reserve costs political capital today and reduces disruption when ordinary procurement fails.',prep('FCU','logistics')+'\nadd_political_power = -25'),
 ('interoperable_workshops','Interoperable Workshops','Compatible gauges, components and repair records will let one district service another district\'s vehicles. Standardisation is a continuing negotiation with suppliers, not a free expansion of industry.','add_tech_bonus = { name = FCU_exp_interoperable_workshops bonus = 0.75 uses = 1 category = industry }'),
 ('civil_protection','A Civil Protection Office','Create a small coordinating office for floods, fires and industrial accidents. Its first task is to identify who can open shelters and restore essential services.','add_stability = 0.02'),
 ('medical_register','Register Medical Capacity','Hospitals will report beds, equipment and transport needs using a common form. The register permits realistic mutual assistance without counting the same emergency team twice.','add_political_power = -15\nadd_manpower = 1000'),
 ('shelter_exercises','Exercise the Shelter Network','A shelter that exists only in a municipal ledger cannot feed an evacuated neighbourhood. Exercises will test access, sanitation and the distribution of supplies.',prep('FCU','relief')),
 ('public_information','A Public Information Charter','Warnings must be credible and comprehensible across several administrations. The council must choose how much information to publish and how much discretion to leave with security officials.',choice('FCU',3)),
 ('joint_inventory','Inventory Collective Readiness','List trained units, available aircraft and escort vessels separately from promised reinforcements. A common inventory gives commanders a realistic starting point.','army_experience = 8\nair_experience = 5'),
 ('staff_exchanges','Exchange Staff Officers','Small staff exchanges will practise liaison and translation of orders. No new faction is created; participating officers remain under their national commands.','army_experience = 12'),
 ('warning_drills','Air-Warning Drills','Radar crews will rehearse the handover of tracks and identification reports. A disciplined reporting chain is more valuable than an impressive but uncoordinated collection of stations.','air_experience = 12'),
 ('readiness_commitment','A Readiness Commitment','Set aside time for recurring joint exercises and verify transport arrangements. The commitment preserves the lessons of the opening programme for the later Usean emergency.',prep('FCU','readiness')+'\nadd_political_power = -25')]
for tag,rows in [('ERU',ERU),('FCU',FCU)]:
    for i,(suffix,title,desc,reward) in enumerate(rows):
        branch,step=divmod(i,4)
        parent=tag+'_exp_'+('opening' if step==0 else rows[i-1][0])
        f(tag,suffix,title,desc,2+branch*5,step+1,[parent],reward,cost=10 if step==3 else 5)
    f(tag,'opening_assessment','Assess the Opening Programme','The cabinet will review the programme that has actually been completed. Further work can continue, but the government must now decide whether to preserve administrative capacity or spend its political reserve on an immediate improvement.',10,5,[tag+'_exp_'+rows[i][0] for i in (3,7,11,15)],assessment(tag))

def later(tag,suffix,title,desc,x,y,parents=(),reward='',available='',cost=5):
    return f(tag,suffix,title,desc,x,y,parents,reward,available,cost,phase='later')

later('ERU','service_register','Restore the Service Register','The post-impact census must connect displaced households to working clinics and water supplies. Opening-era civil records, where they survived, will reduce the administrative burden.',20,2,['rebuild_farbanti'],recovery()+ '\n'+choice('ERU',2))
later('ERU','camp_administration','Professional Camp Administration','Quotas create obligations as well as a limit on admissions. Employ civilian administrators and publish supply accounts so that the camps do not become permanent improvised garrisons.',20,3,['refugee_quotas'],pressure()+'\nadd_political_power = -20')
later('ERU','border_inspection','Inspect the Closed Frontier','A closed border still needs a procedure for medical emergencies and separated families. Inspectors will make commanders accountable for exceptions rather than leaving each crossing to invent its own rules.',24,3,['close_the_border'], 'add_stability = 0.02\n'+choice('ERU',3))
later('ERU','air_repair','Disperse Aircraft Repair','Break up the largest maintenance queues and send repair teams to secondary fields. The air arm will gain usable experience while accepting the cost of a less concentrated supply system.',20,5,['air_arm'],'air_experience = 15\nadd_political_power = -15')
later('ERU','fleet_stores','Fleet Stores and Damage Control','The fleet needs trained damage-control parties and reliable stores ashore. The programme improves endurance without creating ships or rewriting the outcome of a naval battle.',24,5,['aegir_fleet'],'navy_experience = 15')
later('ERU','distributed_depots','Distribute the Army Depots','Move part of the army reserve into smaller depots. Local commanders gain resilience at the expense of additional inspection and transport work.',28,5,['army_modernization'],'army_experience = 12\nadd_political_power = -15')
later('ERU','armistice_commission','An Armistice Commission','A ceasefire needs a record of incidents and a means of returning people across the line. A domestic commission will prepare claims without assuming that the other side will accept them.',20,13,['armistice_line'],recovery(5),outcome('stalemate'))
later('ERU','reconstruction_oversight','Account for Reconstruction Credit','After defeat, reconstruction depends on confidence that supplies reach civilian services. Transparent accounts improve recovery while consuming authority that the provisional administration can ill afford to spare.',24,13,['rebuild_under_oversight'],recovery(6)+'\nadd_political_power = -20',outcome('isaf_victory'))
later('ERU','occupation_review','Review the Cost of Victory','Victory has left Erusea responsible for a wider security system. Review garrison commitments and demobilise unnecessary administrative units before the cost undermines domestic recovery.',28,13,['garrison_the_continent'],recovery(4)+'\nadd_war_support = -0.02',outcome('erusean_victory'))
later('ERU','peace_administration','Administer the Continental Peace','An avoided war needs institutions capable of handling the disputes that remain. Fund the civilian offices that can turn a diplomatic accord into ordinary, predictable relations.',32,7,['continental_accord'],recovery(6)+'\nadd_political_power = -20',outcome('peace'),10)
later('ERU','resettlement','Permanent Resettlement Offices','Temporary relief becomes a permanent problem when families cannot recover documents or livelihoods. Resettlement offices will convert emergency files into durable municipal responsibilities.',32,13,['recovery_decade','rebuild_under_oversight','garrison_the_continent'],pressure(-5)+'\n'+choice('ERU',3))
later('ERU','settlement_assessment','Assess the Erusean Settlement','The outcome may be victory, defeat, an armistice or a war avoided. The cabinet must judge the institutions it actually controls and choose how to finance their next stage of recovery.',24,14,['exp_armistice_commission','exp_reconstruction_oversight','exp_occupation_review','exp_peace_administration'],assessment('ERU'))

later('FCU','burden_review','Review Coalition Burdens','The first relief effort reveals the difference between pledged assistance and delivered supplies. Reconcile contributions with actual capacity before the shortfall turns partners against one another.',20,2,['relief_camps'],recovery(3)+'\n'+choice('FCU',2))
later('FCU','camp_audits','Audit the Relief Camps','Compare camp registers with deliveries and medical reports. Better accounting reduces waste, but requires political backing against officials who prefer the emergency to remain opaque.',20,3,['exp_burden_review'],pressure(-4)+'\nadd_political_power = -15')
later('FCU','transport_board','The Relief Transport Board','Reserve transport for medical supplies and reconstruction equipment. The board coordinates existing carriers rather than promising an unlimited fleet.',24,3,['continental_economy'],recovery(4))
later('FCU','staff_training','Train Coalition Liaison Staff','National headquarters must understand one another before combat makes every misunderstanding urgent. Liaison training improves command practice without altering faction membership.',20,4,['uto_readiness'],'army_experience = 12')
later('FCU','radar_reporting','A Common Air Picture','Agree on track numbering and handover procedures. Better reporting makes the surviving radar network useful even when individual stations are lost.',24,4,['early_warning'],'air_experience = 12')
later('FCU','escort_schedules','Schedule the Escort Groups','Landing vessels and relief ships compete for escort time. A common schedule will protect essential sailings and make the cost of lower-priority missions explicit.',20,9,['amphibious_lift'],'navy_experience = 15')
later('FCU','air_recovery','Recover Aircraft Between Sorties','Forward maintenance parties will salvage usable aircraft and return pilots to their units. Recovery work is a practical complement to the training of replacement squadrons.',24,9,['air_wings'],'air_experience = 15')
later('FCU','field_hospitals','Hospitals Behind the Beachheads','Medical and transport officers will plan evacuation together. The aim is to reduce disruption behind the landing force, not to replace the force\'s combat decisions.',28,10,['landing'],recovery(3)+'\nadd_manpower = 1500')
later('FCU','reconstruction_accounts','Joint Reconstruction Accounts','The provisional settlement needs an account of what assistance has arrived in Erusea and what has been spent at home. Verification strengthens recovery without granting the secretariat new territorial powers.',20,13,['oversee_erusea'],recovery(5)+'\nadd_political_power = -20',outcome('isaf_victory'))
later('FCU','armistice_guarantees','Prepare Armistice Guarantees','An inconclusive war leaves transport routes and displaced communities exposed. Prepare a civilian incident register and a limited reserve of emergency supplies.',24,13,['continental_order'],pressure(-5),outcome('stalemate'))
later('FCU','peace_commission','A Commission for the Peace Dividend','Without a continental war, the treaty can redirect part of its emergency apparatus to public services. The commission will record the remaining obligations before authorising new spending.',28,5,['peace_dividend'],recovery(5)+'\nadd_war_support = -0.02',outcome('peace'),10)
later('FCU','defeat_recovery','Preserve the Civil Network','An Erusean victory does not remove the duty to maintain civilian services. Retain local records and technical staff so that recovery can proceed within the settlement that actually exists.',28,13,['continental_order'],recovery(6),outcome('erusean_victory'))
later('FCU','repatriation','Coordinate Voluntary Returns','Families need documentation, transport and credible information before they can return. The treaty offices will organise assistance without declaring a compulsory return or changing ownership of territory.',32,13,['continental_order','peace_dividend'],pressure(-4)+'\n'+choice('FCU',3))
later('FCU','reserve_integration','Integrate the Relief Reserve','Experienced reserve officers and civilian logisticians will write a common mobilisation handbook. Their work remains useful whether the coalition fought, negotiated or avoided war.',32,6,['draft_charter','peace_dividend'],'army_experience = 10\n'+choice('FCU',3))
later('FCU','settlement_assessment','Assess the Collective Settlement','A treaty survives by making its obligations credible. The council will assess the outcome reached and decide whether to preserve a standing recovery service or release its resources immediately.',24,14,['exp_reconstruction_accounts','exp_armistice_guarantees','exp_peace_commission','exp_defeat_recovery'],assessment('FCU'))

def support(tag,suffix,title,desc,x,y,parents=(),reward='',available='',cost=5):
    return f(tag,suffix,title,desc,x,y,parents,reward,available,cost,phase='support')

support('NPT','island_accounts','The Island Accounts','North Point\'s ministries must reconcile the cost of imported fuel, coastal transport and defence. An honest account will give the elected government a practical starting point.',18,0,reward='set_country_flag = NPT_exp_opening_ready')
support('NPT','mandate_review','Translate the Mandate into Policy','The election determined who governs; it did not settle every allocation. The cabinet will choose how closely public scrutiny should follow emergency administration.',18,2,['NPT_old_guard_mandate','NPT_drp_mandate','NPT_reformist_mandate'],choice('NPT',2))
support('NPT','harbour_repairs','Repair the Coastal Harbours','Small harbour repairs keep food and fuel moving when the main terminal is congested. The programme favours reliable access over a prestige expansion.',22,1,['NPT_exp_island_accounts'],'navy_experience = 8\nadd_political_power = -15')
support('NPT','fishing_cooperatives','The Fishing Cooperatives','Cooperatives will pool cold storage and repair capacity. Their contracts give coastal communities a stake in maintaining services during a wider emergency.',22,2,['NPT_exp_harbour_repairs'],'add_stability = 0.02')
support('NPT','island_workshops','Island Repair Workshops','Domestic workshops can replace imported fittings and repair ground equipment. Supporting those skills reduces disruption without making the island economically self-sufficient.',22,3,['NPT_self_reliant_industry'],'add_tech_bonus = { name = NPT_exp_island_workshops bonus = 0.75 uses = 1 category = industry }')
support('NPT','runway_teams','Dispersed Runway Teams','Train mobile teams to repair damaged runways and move essential equipment between airfields. The same crews can restore civilian access after severe weather.',26,3,['NPT_island_air_defence'],'air_experience = 12')
support('NPT','civil_warning','Civil Air-Warning Procedures','Radar reports must reach local authorities in time to matter. A tested warning procedure reduces confusion without placing all civilian administration under military command.',26,4,['NPT_exp_runway_teams'],'add_stability = 0.02\n'+choice('NPT',3))
support('NPT','humanitarian_stores','Humanitarian Stores','Rotate relief supplies through island warehouses and rehearse their distribution. The stores serve civilian emergencies regardless of the eventual alignment decision.',18,3,['NPT_exp_mandate_review'],'add_political_power = -25\n'+prep('NPT','relief'))
support('NPT','medical_shuttle','An Island Medical Shuttle','Harbour and airfield officers will coordinate patient transport. Keeping one allocation for civilians prevents military traffic from consuming the entire island network.',18,4,['NPT_exp_humanitarian_stores'],'add_manpower = 1000\nadd_stability = 0.01')
support('NPT','neutral_inspections','Neutral Harbour Inspections','Guarded neutrality requires consistent port inspections. Clear procedures reduce the chance that a local dispute will make the government\'s declared policy meaningless.',22,6,['NPT_guarded_neutrality'],'navy_experience = 10\nadd_political_power = -10')
support('NPT','neutral_relief','Relief under Neutral Colours','North Point can maintain civilian relief capability without accepting an allied headquarters. The government will keep humanitarian allocations separate from its military commitments.',22,7,['NPT_exp_neutral_inspections'],'add_stability = 0.03\n'+assessment('NPT'),cost=10)
support('NPT','airfield_services','Services for Visiting Aircrews','Opening the airfields creates work for medical teams, mechanics and civil authorities. Establish clear responsibilities before temporary deployments become a permanent burden.',26,6,['NPT_open_the_airfields'],'air_experience = 12')
support('NPT','allied_transport','An Allied Transport Desk','Coordinate visiting transport with the island\'s own supply needs. The desk supports the existing hosting agreement and claims no authority to create or lead a faction.',26,7,['NPT_isaf_logistics_hub'],recovery(4)+'\nnavy_experience = 10')
support('NPT','hosting_accounts','Account for the Hosting Burden','An allied rear base must remain a functioning island economy. Review the costs borne by communities around the airfields and preserve compensation records.',26,8,['NPT_exp_allied_transport'],'add_political_power = -20\nadd_stability = 0.03\n'+assessment('NPT'),cost=10)
support('NPT','civil_resilience','An Island that Can Endure','The civilian network remains useful even when diplomatic partners are unavailable. Consolidate the medical and repair services so the island has a viable conclusion to its domestic programme.',18,5,['NPT_exp_medical_shuttle'],assessment('NPT')+'\nadd_stability = 0.01')

support('REC','district_inventory','Inventory the District Offices','Recta needs to know which offices are functioning and which records survived. The inventory concerns the territory already administered by the republic and makes no new territorial claim.',18,0,reward='set_country_flag = REC_exp_opening_ready')
support('REC','reconstruction_register','The Reconstruction Register','After the existing settlement has been accepted, local offices can register damaged housing and public works. A public register makes competing claims visible before funds are assigned.',18,2,['REC_local_recovery_programme'],choice('REC',2))
support('REC','rail_workshops','Reopen the Rail Workshops','Repair crews will restore locomotives and freight wagons before planning a larger network. Skilled workers and usable parts are the immediate limits on reconstruction.',22,3,['REC_exp_reconstruction_register'],'add_tech_bonus = { name = REC_exp_rail_workshops bonus = 0.75 uses = 1 category = industry }')
support('REC','municipal_accounts','Publish Municipal Accounts','Standard accounts let the administration compare district needs. Publishing them consumes political authority but limits the cost of rebuilding the same service twice.',18,3,['REC_exp_reconstruction_register'],'add_political_power = -15\nadd_stability = 0.02')
support('REC','security_review','Review the Security Apparatus','The hardline programme needs a review of who can issue orders and who can investigate abuses. Its political purpose is preserved, but indiscriminate requisitioning must stop disrupting recovery.',26,4,['REC_party_security_organs'],choice('REC',3)+'\narmy_experience = 8')
support('REC','council_audit','Audit the Economic Councils','Reform has transferred decisions to councils with uneven experience. A common audit procedure will identify shortages without reversing the political choice that created the councils.',30,4,['REC_economic_councils'],choice('REC',3)+'\nadd_stability = 0.02')
support('REC','gebet_standards','Technical Standards with Gebet','Prepare compatible inspection and repair procedures for trade with Gebet. Domestic workshops keep the technical lessons even if diplomatic cooperation later becomes impossible.',22,4,['REC_gebet_economic_compact'],'add_tech_bonus = { name = REC_exp_gebet_standards bonus = 0.5 uses = 1 category = industry }')
support('REC','border_services','Civil Services at the Frontier','A border guard needs customs clerks, interpreters and medical support. Improving those services reduces friction without redrawing the frontier.',18,4,['REC_rectan_border_guard'],'add_stability = 0.02')
support('REC','fato_liaison','A FATO Liaison Office','The partnership requires a reliable channel for ordinary administrative work. The office will prepare requests and maintain domestic records without changing faction ownership.',22,5,['REC_fato_partnership'],'army_experience = 10')
support('REC','independent_recovery','Recovery on Rectan Terms','Distance from FATO leaves more responsibility with domestic institutions. Preserve the workshop and municipal networks needed to sustain that choice.',18,5,['REC_fato_distance'],'add_political_power = -20\nadd_stability = 0.03')
support('REC','recovery_assessment','Assess the Rectan Recovery','The republic will assess the recovery achieved within its existing settlement. The cabinet can preserve a standing service or use the accumulated capacity for a final immediate improvement.',22,6,['REC_exp_fato_liaison','REC_exp_independent_recovery'],assessment('REC'),cost=10)

support('YUK','industrial_inventory','Inventory the Industrial Ministries','Yuktobania\'s industrial ministries must distinguish planned capacity from machines and crews ready for use. A common inventory gives the civilian and military programmes a realistic foundation.',18,0,reward='set_country_flag = YUK_exp_opening_ready')
support('YUK','rail_dispatch','Modernise Rail Dispatch','Dispatch offices will share maintenance closures and freight priorities. Better information improves the existing network before the government commits to expensive expansion.',18,1,['YUK_exp_industrial_inventory'],'add_tech_bonus = { name = YUK_exp_rail_dispatch bonus = 0.5 uses = 1 category = industry }')
support('YUK','machine_contracts','Civil Machine-Tool Contracts','Predictable civilian orders can sustain workshops between military contracts. The cabinet must decide how much discretion to leave with ministries and how much scrutiny to permit.',22,1,['YUK_exp_industrial_inventory'],choice('YUK',2))
support('YUK','regional_depots','Regional Supply Depots','Distribute essential spares across regional depots. The programme requires more inspection work, but reduces reliance on a single large storage and dispatch centre.',18,2,['YUK_exp_rail_dispatch'],'army_experience = 8\nadd_political_power = -15')
support('YUK','production_audit','An Audit of Production Claims','Compare deliveries with the ministries\' production claims. Reward reliable suppliers and expose bottlenecks before another emergency encourages optimistic reporting.',22,2,['YUK_exp_machine_contracts'],'add_stability = 0.02')
support('YUK','veteran_services','Services for Intervention Veterans','The intervention has left medical and administrative obligations. Veteran services will preserve experience while reducing the cost of unresolved claims on the command system.',26,3,['YUK_volunteer_veterans'],'add_manpower = 1500\nadd_political_power = -20')
support('YUK','expedition_logistics','Study Expeditionary Logistics','Staff officers will examine the transport and maintenance costs of intervention. The lessons improve planning without committing Yuktobania to another foreign deployment.',26,4,['YUK_expeditionary_command'],'army_experience = 15\n'+choice('YUK',3))
support('YUK','delegated_inspection','Inspect Delegated Commands','Command reform needs a way to evaluate initiative without recreating central micromanagement. Inspection teams will compare readiness and maintenance outcomes rather than the volume of reports.',30,3,['YUK_delegate_field_initiative'],'army_experience = 10')
support('YUK','reform_logistics','Logistics for the Reformed Army','Regional commanders need reliable supply authority if delegated initiative is to mean anything. Codify procurement limits and the support available from the central ministries.',30,4,['YUK_reformed_field_command'],'army_experience = 15\n'+choice('YUK',3))
support('YUK','command_assessment','Assess Command Responsibility','The army will review the consequences of its chosen command path. Both intervention experience and institutional reform can inform the assessment, but neither erases the other\'s political cost.',28,5,['YUK_exp_expedition_logistics','YUK_exp_reform_logistics'],assessment('YUK'),cost=10)
support('YUK','civil_observatories','Fund Civil Observatories','Civilian observatories will improve tracking and train technicians. The work provides a domestic scientific foundation independently of any later Arkbird partnership.',22,3,['YUK_exp_production_audit'],'add_tech_bonus = { name = YUK_exp_civil_observatories bonus = 0.5 uses = 1 category = electronics }')
support('YUK','tracking_archives','Preserve the Tracking Archives','Observations need consistent timestamps and accessible records. A civilian archive allows later scientists to test earlier conclusions instead of relying on institutional memory.',22,4,['YUK_exp_civil_observatories'],'add_stability = 0.01\n'+choice('YUK',3))
support('YUK','arkbird_science','Civil Science from Arkbird','The established cooperation programme has produced expertise as well as debris observations. Civil laboratories will study that knowledge within the existing partnership, without claiming control of the project itself.',18,6,['YUK_civil_space_cooperation'],'add_tech_bonus = { name = YUK_exp_arkbird_science bonus = 0.75 uses = 1 category = electronics }')
support('YUK','data_protocols','Prepare Scientific Data Protocols','Prepare a domestic standard for publishing orbital observations. Bilateral publication proceeds only while Osea and Yuktobania remain independent, at peace with each other and able to cooperate. A failed partnership leaves the domestic archive useful.',18,7,['YUK_exp_arkbird_science'],'add_stability = 0.02')
support('YUK','civil_science_assessment','Assess Civilian Space Cooperation','The civilian programme will assess the scientific value of the partnership and the cost of maintaining its institutions. The assessment does not grant project completion or transfer control of Arkbird.',18,8,['YUK_exp_data_protocols'],assessment('YUK'),cost=10)
